    /// <summary>
    /// Encadena una función que devuelve un resultado de <c>Multi</c>. Versión asíncrona.
    /// </summary>
    /// <typeparam name="T">Tipo del valor transportado por el resultado.</typeparam>
    /// <typeparam name="TResult">Tipo del valor devuelto.</typeparam>
    /// <typeparam name="TFuncColec">Tipo genérico TFuncColec.</typeparam>
    /// <param name="source">Resultado de origen sobre el que se aplica la operación.</param>
    /// <param name="returnFuncAsync">Función a aplicar.</param>
    /// <param name="funcsAsync">Función a aplicar.</param>
    /// <returns>Tarea que produce el resultado válido con el valor obtenido, o resultado fallido con los detalles del error.</returns>
    public static Task<MlResult<TResult>> BindMultiAsync<T, TResult, TFuncColec>(this   MlResult<T>                           source,
                                                                                        Func<T,
                                                                                             IEnumerable<TFuncColec>,
                                                                                             Task<MlResult<TResult>>>         returnFuncAsync,
                                                                                 params Func<T, Task<MlResult<TFuncColec>>>[] funcsAsync)
        => source.MatchAsync
        (
            failAsync: errorsDetails => MlResult<TResult>.FailAsync(errorsDetails),
            validAsync: async value =>
            {
                List<MlResult<TFuncColec>> resultsData = [];
                foreach (var funcAsync in funcsAsync)
                {
                    var funcResult = await funcAsync(value);
                    resultsData.Add(funcResult);
                }
                var partialResult = resultsData.Any(x => x.IsFailure)
                                        ? await resultsData.MergeFailureErrorsAsync().GetFailureDetailsOrThrowAsync()
                                        : await returnFuncAsync(value,
                                                                resultsData.Where(x => x.IsSuccess).Select(y => y.GetValueOrThrow()));
                return partialResult;
            }
        );

